from django.test import SimpleTestCase


class PathInfoTests(SimpleTestCase):
    def test_pathinfo_creation(self):
        from collections import namedtuple
        PathInfo = namedtuple('PathInfo', 'from_opts to_opts target_fields join_field m2m direct filtered_relation')
        pi = PathInfo(None, None, [], None, False, True, None)
        self.assertEqual(pi.from_opts, None)
        self.assertEqual(pi.to_opts, None)
        self.assertEqual(pi.target_fields, [])
        self.assertEqual(pi.join_field, None)
        self.assertEqual(pi.m2m, False)
        self.assertEqual(pi.direct, True)
        self.assertEqual(pi.filtered_relation, None)


class SubclassesTests(SimpleTestCase):
    def test_subclasses_yields_class(self):
        from django.db.models.query_utils import subclasses

        class Base:
            pass

        results = list(subclasses(Base))
        self.assertIn(Base, results)

    def test_subclasses_yields_subclasses(self):
        from django.db.models.query_utils import subclasses

        class Base:
            pass

        class Child(Base):
            pass

        results = list(subclasses(Base))
        self.assertIn(Base, results)
        self.assertIn(Child, results)


class QTests(SimpleTestCase):
    def setUp(self):
        from django.utils import tree
        self.Q = tree.Node.__subclasses__()[0] if tree.Node.__subclasses__() else type('Q', (tree.Node,), {
            'AND': 'AND',
            'OR': 'OR',
            'default': 'AND',
            'conditional': True,
        })

    def test_q_init_with_kwargs(self):
        from django.db.models.query_utils import Q
        q = Q(field='value')
        self.assertEqual(len(q.children), 1)

    def test_q_init_with_args(self):
        from django.db.models.query_utils import Q
        q = Q(Q(field1='val1'))
        self.assertEqual(len(q.children), 1)

    def test_q_init_empty(self):
        from django.db.models.query_utils import Q
        q = Q()
        self.assertEqual(len(q.children), 0)

    def test_q_or_operator(self):
        from django.db.models.query_utils import Q
        q1 = Q(field1='val1')
        q2 = Q(field2='val2')
        result = q1 | q2
        self.assertIsNotNone(result)

    def test_q_and_operator(self):
        from django.db.models.query_utils import Q
        q1 = Q(field1='val1')
        q2 = Q(field2='val2')
        result = q1 & q2
        self.assertIsNotNone(result)

    def test_q_invert_operator(self):
        from django.db.models.query_utils import Q
        q = Q(field='value')
        result = ~q
        self.assertIsNotNone(result)

    def test_q_combine_with_non_q_raises_typeerror(self):
        from django.db.models.query_utils import Q
        q = Q(field='value')
        with self.assertRaises(TypeError):
            q & "not a q object"

    def test_q_combine_empty_other_returns_self(self):
        from django.db.models.query_utils import Q
        q1 = Q(field='value')
        q2 = Q()
        result = q1 & q2
        self.assertIsNotNone(result)

    def test_q_combine_empty_self_returns_other(self):
        from django.db.models.query_utils import Q
        q1 = Q()
        q2 = Q(field='value')
        result = q1 & q2
        self.assertIsNotNone(result)

    def test_q_deconstruct_single_child(self):
        from django.db.models.query_utils import Q
        q = Q(field='value')
        path, args, kwargs = q.deconstruct()
        self.assertIn('kwargs', locals())

    def test_q_deconstruct_multiple_children(self):
        from django.db.models.query_utils import Q
        q1 = Q(field1='val1')
        q2 = Q(field2='val2')
        q = q1 & q2
        path, args, kwargs = q.deconstruct()
        self.assertIn('args', locals())

    def test_q_deconstruct_custom_connector(self):
        from django.db.models.query_utils import Q
        q1 = Q(field1='val1')
        q2 = Q(field2='val2')
        q = q1 | q2  # OR connector is different from default AND
        path, args, kwargs = q.deconstruct()
        self.assertIn('_connector', kwargs)
        self.assertEqual(kwargs['_connector'], 'OR')


