    def test_deferredattribute_check_parent_chain_with_pk(self):
        from django.db.models.query_utils import DeferredAttribute

        class MockLinkField:
            attname = 'link_id'

        class MockField:
            attname = 'test_field'
            primary_key = True
            model = None
            __eq__ = lambda self, other: False

        class MockMeta:
            def get_ancestor_link(self, model):
                return MockLinkField()

        class MockInstance:
            _meta = MockMeta()

            def __getattr__(self, name):
                if name == 'link_id':
                    return 42
                raise AttributeError(name)

        field = MockField()
        da = DeferredAttribute(field)
        instance = MockInstance()
        result = da._check_parent_chain(instance)
        self.assertEqual(result, 42)

    def test_deferredattribute_check_parent_chain_returns_value_caches_it(self):
        from django.db.models.query_utils import DeferredAttribute

        class MockLinkField:
            attname = 'link_id'

        class MockField:
            attname = 'test_field'
            primary_key = True
            model = None
            __eq__ = lambda self, other: False

        class MockMeta:
            def get_ancestor_link(self, model):
                return MockLinkField()

        class MockInstance:
            __dict__ = {}
            _meta = MockMeta()

            def __getattr__(self, name):
                if name == 'link_id':
                    return 42
                raise AttributeError(name)

        field = MockField()
        da = DeferredAttribute(field)
        instance = MockInstance()
        result = da._check_parent_chain(instance)
        self.assertEqual(result, 42)
        # Verify it was cached
        self.assertIn('test_field', instance.__dict__)
        self.assertEqual(instance.__dict__['test_field'], 42)


class RegisterLookupMixinTests(SimpleTestCase):
    def test_registerlookuppixin_get_lookup(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class TestClass(RegisterLookupMixin):
            pass

        result = TestClass._get_lookup('test_lookup')
        self.assertIsNone(result)

    def test_registerlookuppixin_merge_dicts(self):
        from django.db.models.query_utils import RegisterLookupMixin

        d1 = {'a': 1, 'b': 2}
        d2 = {'b': 3, 'c': 4}
        result = RegisterLookupMixin.merge_dicts([d1, d2])
        self.assertEqual(result['a'], 1)
        self.assertEqual(result['b'], 2)
        self.assertEqual(result['c'], 4)

    def test_registerlookuppixin_register_lookup(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class MockLookup:
            lookup_name = 'test_lookup'

        class TestClass(RegisterLookupMixin):
            pass

        mock_lookup = MockLookup()
        result = TestClass.register_lookup(mock_lookup)
        self.assertEqual(result, mock_lookup)
        self.assertIn('test_lookup', TestClass.class_lookups)

    def test_registerlookuppixin_unregister_lookup(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class MockLookup:
            lookup_name = 'test_lookup'

        class TestClass(RegisterLookupMixin):
            class_lookups = {'test_lookup': MockLookup()}

        mock_lookup = MockLookup()
        TestClass._unregister_lookup(mock_lookup)
        self.assertNotIn('test_lookup', TestClass.class_lookups)

    def test_registerlookuppixin_get_lookup_with_output_field(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class MockOutputField:
            def get_lookup(self, name):
                return f'found_{name}'

        class TestClass(RegisterLookupMixin):
            output_field = MockOutputField()

        tc = TestClass()
        result = tc.get_lookup('custom_lookup')
        self.assertEqual(result, 'found_custom_lookup')

    def test_registerlookuppixin_get_lookup_returns_none_for_invalid(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class TestClass(RegisterLookupMixin):
            pass

        tc = TestClass()
        result = tc.get_lookup('nonexistent_lookup')
        self.assertIsNone(result)

    def test_registerlookuppixin_get_transform_with_output_field(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class MockOutputField:
            def get_transform(self, name):
                return f'transform_{name}'

        class TestClass(RegisterLookupMixin):
            output_field = MockOutputField()

        tc = TestClass()
        result = tc.get_transform('custom_transform')
        self.assertEqual(result, 'transform_custom_transform')


