class RefsExpressionTests(SimpleTestCase):
    def test_refs_expression_no_match(self):
        from django.db.models.query_utils import refs_expression

        annotations = {}
        lookup_parts = ['field', 'subfield']
        result, remaining = refs_expression(lookup_parts, annotations)
        self.assertFalse(result)
        self.assertEqual(remaining, ())

    def test_refs_expression_full_match(self):
        from django.db.models.query_utils import refs_expression

        annotations = {'field__subfield': 'annotation_obj'}
        lookup_parts = ['field', 'subfield']
        result, remaining = refs_expression(lookup_parts, annotations)
        self.assertEqual(result, 'annotation_obj')
        self.assertEqual(remaining, [])

    def test_refs_expression_partial_match(self):
        from django.db.models.query_utils import refs_expression

        annotations = {'field': 'annotation_obj'}
        lookup_parts = ['field', 'subfield']
        result, remaining = refs_expression(lookup_parts, annotations)
        self.assertEqual(result, 'annotation_obj')
        self.assertEqual(remaining, ['subfield'])


