class FilteredRelationTests(SimpleTestCase):
    def test_filteredrelation_init_valid(self):
        from django.db.models.query_utils import FilteredRelation, Q

        fr = FilteredRelation('relation_name')
        self.assertEqual(fr.relation_name, 'relation_name')
        self.assertIsNone(fr.alias)
        self.assertIsInstance(fr.condition, Q)
        self.assertEqual(fr.path, [])

    def test_filteredrelation_init_empty_relation_name_raises_valueerror(self):
        from django.db.models.query_utils import FilteredRelation

        with self.assertRaises(ValueError):
            FilteredRelation('')

    def test_filteredrelation_init_empty_string_raises_valueerror(self):
        from django.db.models.query_utils import FilteredRelation

        with self.assertRaises(ValueError):
            FilteredRelation('')

    def test_filteredrelation_init_invalid_condition_raises_valueerror(self):
        from django.db.models.query_utils import FilteredRelation

        with self.assertRaises(ValueError):
            FilteredRelation('relation_name', condition='not a Q')

    def test_filteredrelation_eq_same(self):
        from django.db.models.query_utils import FilteredRelation, Q

        fr1 = FilteredRelation('relation_name', condition=Q(field='value'))
        fr2 = FilteredRelation('relation_name', condition=Q(field='value'))
        self.assertEqual(fr1, fr2)

    def test_filteredrelation_eq_different_relation_name(self):
        from django.db.models.query_utils import FilteredRelation, Q

        fr1 = FilteredRelation('relation_name1', condition=Q(field='value'))
        fr2 = FilteredRelation('relation_name2', condition=Q(field='value'))
        self.assertNotEqual(fr1, fr2)

    def test_filteredrelation_eq_different_alias(self):
        from django.db.models.query_utils import FilteredRelation, Q

        fr1 = FilteredRelation('relation_name', condition=Q(field='value'))
        fr1.alias = 'alias1'
        fr2 = FilteredRelation('relation_name', condition=Q(field='value'))
        fr2.alias = 'alias2'
        self.assertNotEqual(fr1, fr2)

    def test_filteredrelation_eq_different_condition(self):
        from django.db.models.query_utils import FilteredRelation, Q

        fr1 = FilteredRelation('relation_name', condition=Q(field='value'))
        fr2 = FilteredRelation('relation_name', condition=Q(other='other'))
        self.assertNotEqual(fr1, fr2)

    def test_filteredrelation_eq_different_class(self):
        from django.db.models.query_utils import FilteredRelation, Q

        fr1 = FilteredRelation('relation_name', condition=Q(field='value'))
        fr2 = {'relation_name': 'relation_name'}
        result = fr1 == fr2
        self.assertFalse(result or result is NotImplemented)

    def test_filteredrelation_clone(self):
        from django.db.models.query_utils import FilteredRelation, Q

        fr = FilteredRelation('relation_name', condition=Q(field='value'))
        fr.alias = 'test_alias'
        fr.path = ['path1', 'path2']

        clone = fr.clone()
        self.assertEqual(clone.relation_name, fr.relation_name)
        self.assertEqual(clone.alias, fr.alias)
        self.assertEqual(clone.path, fr.path[:])

    def test_filteredrelation_resolve_expression_raises_notimplemented(self):
        from django.db.models.query_utils import FilteredRelation

        fr = FilteredRelation('relation_name')
        with self.assertRaises(NotImplementedError):
            fr.resolve_expression()

from django.contrib.auth.hashers import UNUSABLE_PASSWORD_PREFIX
from django.core.exceptions import ValidationError
from django.test import SimpleTestCase, TestCase


class UnicodeCompareTests(SimpleTestCase):
    """Tests for _unicode_ci_compare function."""

    def setUp(self):
        from django.contrib.auth.forms import _unicode_ci_compare
        self._unicode_ci_compare = _unicode_ci_compare

    def test_unicode_ci_compare_equal(self):
        result = self._unicode_ci_compare('hello', 'HELLO')
        self.assertTrue(result)

    def test_unicode_ci_compare_different(self):
        result = self._unicode_ci_compare('hello', 'world')
        self.assertFalse(result)

    def test_unicode_ci_compare_normalized(self):
        # Test NFKC normalization
        result = self._unicode_ci_compare('iamtheΩ', 'iamtheΩ')  # Omega vs Ohm sign
        self.assertTrue(result)

    def test_unicode_ci_compare_empty_strings(self):
        result = self._unicode_ci_compare('', '')
        self.assertTrue(result)

    def test_unicode_ci_compare_one_empty(self):
        result = self._unicode_ci_compare('', 'hello')
        self.assertFalse(result)


