class UserCreationFormTests(TestCase):
    """Tests for UserCreationForm class."""
    databases = {'default'}

    def setUp(self):
        from django.contrib.auth.forms import UserCreationForm
        self.form_class = UserCreationForm

    def test_form_fields_exist(self):
        form = self.form_class()
        self.assertIn('username', form.fields)
        self.assertIn('password1', form.fields)
        self.assertIn('password2', form.fields)

    def test_password_mismatch_error(self):
        form = self.form_class(data={
            'username': 'testuser',
            'password1': 'password123',
            'password2': 'differentpassword',
        })
        self.assertFalse(form.is_valid())
        self.assertIn('password2', form.errors)
        self.assertIn("didn't", form.errors['password2'][0])

    def test_password_match_valid(self):
        form = self.form_class(data={
            'username': 'testuser',
            'password1': 'password123',
            'password2': 'password123',
        })
        self.assertTrue(form.is_valid())

    def test_clean_password2_returns_password2(self):
        form = self.form_class(data={
            'username': 'testuser',
            'password1': 'password123',
            'password2': 'password123',
        })
        form.is_valid()
        self.assertEqual(form.cleaned_data['password2'], 'password123')

    def test_password1_help_text_includes_validators(self):
        form = self.form_class()
        help_text = form.fields['password1'].help_text
        self.assertIn('character', help_text.lower())

    def test_password2_help_text(self):
        form = self.form_class()
        help_text = form.fields['password2'].help_text
        self.assertIn('verification', help_text.lower())

    def test_save_creates_user(self):
        form = self.form_class(data={
            'username': 'testuser',
            'password1': 'password123',
            'password2': 'password123',
        })
        form.is_valid()
        user = form.save()
        self.assertEqual(user.username, 'testuser')
        self.assertTrue(user.check_password('password123'))


