class TestMultiDecorate(SimpleTestCase):
    """Tests for _multi_decorate function."""

    def setUp(self):
        from django.utils.decorators import _multi_decorate
        self._multi_decorate = _multi_decorate

    def test_single_decorator(self):
        from django.utils.decorators import _multi_decorate

        def decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        class MyClass:
            def method(self):
                return "original"

        decorated = _multi_decorate(decorator, MyClass.method)
        obj = MyClass()
        result = decorated(obj)
        self.assertEqual(result, "original_decorated")

    def test_list_of_decorators(self):
        from django.utils.decorators import _multi_decorate

        def decorator1(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_d1"
            return wrapper

        def decorator2(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_d2"
            return wrapper

        class MyClass:
            def method(self):
                return "original"

        decorated = _multi_decorate([decorator1, decorator2], MyClass.method)
        obj = MyClass()
        result = decorated(obj)
        # Order: decorators are reversed before application, so d2 applied first, then d1
        self.assertEqual(result, "original_d2_d1")

    def test_tuple_of_decorators(self):
        from django.utils.decorators import _multi_decorate

        def decorator1(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_d1"
            return wrapper

        def decorator2(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_d2"
            return wrapper

        class MyClass:
            def method(self):
                return "original"

        decorated = _multi_decorate((decorator1, decorator2), MyClass.method)
        obj = MyClass()
        result = decorated(obj)
        # Order: decorators are reversed before application, so d2 applied first, then d1
        self.assertEqual(result, "original_d2_d1")

    def test_preserves_method_name(self):
        from django.utils.decorators import _multi_decorate

        def decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class MyClass:
            def method(self):
                return "original"

        decorated = _multi_decorate(decorator, MyClass.method)
        self.assertEqual(decorated.__name__, "method")


