            def __html__(self):
                return "html"

        with self.assertRaises(ValueError):
            html_safe(AlreadyHasHtml)

    def test_html_safe_no_str(self):
        from django.utils.html import html_safe

        class NoStr:
            pass

        with self.assertRaises(ValueError):
            html_safe(NoStr)


