            pass

        with mock.patch.object(DatabaseClient.__bases__[0], 'runshell', _mock_super_runshell):
            client.runshell([])

        # Restore original handler after test
        signal.signal(signal.SIGINT, original_handler)

    def test_runshell_sets_sigint_to_ignore_during_execution(self):
        mock_connection = mock.MagicMock()
        client = DatabaseClient(mock_connection)

        result = {'handler': None}

        def _mock_super_runshell(self, parameters):
            handler = signal.getsignal(signal.SIGINT)
            result['handler'] = handler

        with mock.patch.object(DatabaseClient.__bases__[0], 'runshell', _mock_super_runshell):
            client.runshell([])

        self.assertEqual(result['handler'], signal.SIG_IGN)

    def test_runshell_restores_original_handler_after_exception(self):
        original_handler = signal.getsignal(signal.SIGINT)

        mock_connection = mock.MagicMock()
        client = DatabaseClient(mock_connection)

        def _raise_error(self, parameters):
            raise ValueError("Test error")

        try:
            with mock.patch.object(DatabaseClient.__bases__[0], 'runshell', _raise_error):
                try:
                    client.runshell([])
                except ValueError:
                    pass

            # Handler should be restored even after exception
            self.assertEqual(original_handler, signal.getsignal(signal.SIGINT))
        finally:
            signal.signal(signal.SIGINT, original_handler)

