class JoinTests(SimpleTestCase):
    @setup({"join01": "{{ a|join:', ' }}"})
    def test_join01(self):
        output = self.engine.render_to_string(
            "join01", {"a": ["apple", "banana", "cherry"]}
        )
        self.assertEqual(output, "apple, banana, cherry")

    @setup({"join02": "{{ a|join:' - ' }}"})
    def test_join02(self):
        output = self.engine.render_to_string(
            "join02", {"a": ["one", "two", "three"]}
        )
        self.assertEqual(output, "one - two - three")

    @setup({"join03": "{{ a|join:'' }}"})
    def test_join03(self):
        output = self.engine.render_to_string(
            "join03", {"a": ["h", "e", "l", "l", "o"]}
        )
        self.assertEqual(output, "hello")

    @setup({"join04": "{{ a|join:'|' }}"})
    def test_join04(self):
        output = self.engine.render_to_string(
            "join04", {"a": ["x", "y", "z"]}
        )
        self.assertEqual(output, "x|y|z")

    @setup({"join05": "{{ a|join:', ' }} {{ b|join:', ' }}"})
    def test_join05(self):
        output = self.engine.render_to_string(
            "join05",
            {
                "a": ["a&b", "c&d"],
                "b": [mark_safe("a&b"), mark_safe("c&d")],
            },
        )
        self.assertEqual(output, "a&amp;b, c&amp;d a&b, c&d")

    @setup(
        {
            "join06": (
                "{% autoescape off %}{{ a|join:', ' }} {{ b|join:', ' }}{% endautoescape %}"
            )
        }
    )
    def test_join06(self):
        output = self.engine.render_to_string(
            "join06",
            {
                "a": ["a&b", "c&d"],
                "b": [mark_safe("a&b"), mark_safe("c&d")],
            },
        )
        self.assertEqual(output, "a&b, c&d a&b, c&d")

    @setup({"join07": "{{ a|join:', ' }}"})
    def test_join07(self):
        output = self.engine.render_to_string("join07", {"a": []})
        self.assertEqual(output, "")

    @setup({"join08": "{{ a|join:', ' }}"})
    def test_join08(self):
        output = self.engine.render_to_string("join08", {"a": ["single"]})
        self.assertEqual(output, "single")

    @setup({"join09": "{{ a|join:'\\n' }}"})
    def test_join09(self):
        output = self.engine.render_to_string(
            "join09", {"a": ["line1", "line2", "line3"]}
        )
        self.assertEqual(output, "line1\nline2\nline3")

    @setup({"join10": "{{ a|join:' <br> ' }}"})
    def test_join10(self):
        output = self.engine.render_to_string(
            "join10", {"a": ["item1", "item2"]}
        )
        self.assertEqual(output, "item1 &lt;br&gt; item2")


class FunctionTests(SimpleTestCase):
    def test_basic_join(self):
        from django.template.defaultfilters import join
        self.assertEqual(join(["a", "b", "c"], ", "), "a, b, c")

    def test_empty_list(self):
        from django.template.defaultfilters import join
        self.assertEqual(join([], ", "), "")

    def test_single_item(self):
        from django.template.defaultfilters import join
        self.assertEqual(join(["only"], ", "), "only")

    def test_with_special_chars(self):
        from django.template.defaultfilters import join
        result = join(["a<b", "c>d"], " | ")
        self.assertIn("&lt;", result)
        self.assertIn("&gt;", result)

    def test_with_numbers(self):
        from django.template.defaultfilters import join
        result = join([1, 2, 3], "-")
        self.assertEqual(result, "1-2-3")

    def test_with_none_values(self):
        from django.template.defaultfilters import join
        result = join([None, "text", None], ", ")
        self.assertEqual(result, "None, text, None")

    def test_autoescape_false(self):
        from django.template.defaultfilters import join
        result = join(["a&b", "c<d"], " | ", autoescape=False)
        self.assertEqual(result, "a&b | c<d")

    def test_autoescape_true_default(self):
        from django.template.defaultfilters import join
        result = join(["a&b", "c<d"], ", ")
        self.assertIn("&amp;", result)
        self.assertIn("&lt;", result)

    def test_safestring_input(self):
        from django.template.defaultfilters import join
        safe_val = mark_safe("safe content")
        result = join([safe_val, "unsafe"], ", ")
        self.assertIn("safe content", result)

    def test_unicode_separator(self):
        from django.template.defaultfilters import join
        result = join(["a", "b", "c"], " → ")
        self.assertEqual(result, "a → b → c")

    def test_empty_separator(self):
        from django.template.defaultfilters import join
        result = join(["hello", "world"], "")
        self.assertEqual(result, "helloworld")

    def test_multiline_content(self):
        from django.template.defaultfilters import join
        result = join(["line1\nmore", "line2"], " | ")
        self.assertIn("\n", result)

    def test_long_list(self):
        from django.template.defaultfilters import join
        long_list = [str(i) for i in range(100)]
        result = join(long_list, ", ")
        expected = ", ".join(long_list)
        self.assertEqual(result, expected)

    def test_returns_mark_safe(self):
        from django.template.defaultfilters import join
        from django.utils.safestring import SafeData
        result = join(["a", "b"], ", ")
        self.assertIsInstance(result, SafeData)

    def test_typeerror_fails_silently(self):
        from django.template.defaultfilters import join
        # When arg is not iterable, should return original value
        result = join(["a", "b"], None)
        self.assertEqual(result, ["a", "b"])

    def test_mixed_types_in_list(self):
        from django.template.defaultfilters import join
        result = join([1, "text", 3.14], " + ")
        self.assertIn("1", result)
        self.assertIn("text", result)
        self.assertIn("3.14", result)

    def test_whitespace_separator(self):
        from django.template.defaultfilters import join
        result = join(["word1", "word2", "word3"], " ")
        self.assertEqual(result, "word1 word2 word3")

    def test_newline_separator(self):
        from django.template.defaultfilters import join
        result = join(["a", "b", "c"], "\n")
        self.assertEqual(result, "a\nb\nc")

    def test_tab_separator(self):
        from django.template.defaultfilters import join
        result = join(["a", "b", "c"], "\t")
        self.assertEqual(result, "a\tb\tc")

    def test_html_tags_in_content(self):
        from django.template.defaultfilters import join
        result = join(["<script>alert('xss')</script>", "safe"], " | ")
        self.assertIn("&lt;script&gt;", result)

