    def test_init_basic(self):
        autodetector = MigrationAutodetector(self.from_state, self.to_state)
        self.assertIs(autodetector.from_state, self.from_state)
        self.assertIs(autodetector.to_state, self.to_state)
        self.assertIsNotNone(autodetector.questioner)
        self.assertEqual(autodetector.existing_apps, set())

    def test_init_with_questioner(self):
        questioner = mock.MagicMock()
        autodetector = MigrationAutodetector(self.from_state, self.to_state, questioner)
        self.assertIs(autodetector.questioner, questioner)

