class TestJSONFieldInit(SimpleTestCase):
    """Test JSONField initialization."""

    def setUp(self):
        from django.db.models.fields.json import JSONField
        self.JSONField = JSONField

    def test_init_with_valid_encoder_decoder(self):
        """Test initialization with valid encoder and decoder callables."""
        def custom_encoder(obj):
            return str(obj)

        def custom_decoder(obj):
            return obj

