class CheckSettingAppDirsLoadersTest(SimpleTestCase):
    """Tests for check_setting_app_dirs_loaders function."""

    def setUp(self):
        self.app_configs = None

    @override_settings(TEMPLATES=[{"BACKEND": "django.template.backends.django.DjangoTemplates"}])
    def test_no_error_when_app_dirs_false_and_loaders_present(self):
        """No error when APP_DIRS is False even if loaders present."""
        errors = check_setting_app_dirs_loaders(self.app_configs)
        self.assertEqual(errors, [])

    @override_settings(TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "APP_DIRS": True,
        "OPTIONS": {"loaders": ["loader1"]}
    }])
    def test_error_when_app_dirs_true_and_loaders_present(self):
        """Error when APP_DIRS is True and loaders option is present."""
        errors = check_setting_app_dirs_loaders(self.app_configs)
        self.assertEqual(errors, [E001])

    @override_settings(TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "APP_DIRS": True,
    }])
    def test_no_error_when_app_dirs_true_but_no_loaders(self):
        """No error when APP_DIRS is True but no loaders option."""
        errors = check_setting_app_dirs_loaders(self.app_configs)
        self.assertEqual(errors, [])

    @override_settings(TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "OPTIONS": {"loaders": ["loader1"]},
    }])
    def test_no_error_when_app_dirs_not_set_and_loaders_present(self):
        """No error when APP_DIRS not set (defaults to False) and loaders present."""
        errors = check_setting_app_dirs_loaders(self.app_configs)
        self.assertEqual(errors, [])

    @override_settings(TEMPLATES=[
        {
            "BACKEND": "django.template.backends.django.DjangoTemplates",
            "APP_DIRS": True,
        },
        {
            "BACKEND": "django.template.backends.django.DjangoTemplates",
            "APP_DIRS": True,
            "OPTIONS": {"loaders": ["loader1"]}
        },
    ])
    def test_error_when_one_config_has_conflict(self):
        """Error when at least one config has APP_DIRS=True with loaders."""
        errors = check_setting_app_dirs_loaders(self.app_configs)
        self.assertEqual(errors, [E001])

    @override_settings(TEMPLATES=[
        {
            "BACKEND": "django.template.backends.django.DjangoTemplates",
            "APP_DIRS": True,
            "OPTIONS": {"loaders": ["loader1"]},
        },
        {
            "BACKEND": "django.template.backends.django.DjangoTemplates",
            "APP_DIRS": True,
            "OPTIONS": {"loaders": ["loader2"]},
        },
    ])
    def test_error_when_multiple_configs_have_conflict(self):
        """Error when multiple configs have APP_DIRS=True with loaders."""
        errors = check_setting_app_dirs_loaders(self.app_configs)
        self.assertEqual(errors, [E001])

    @override_settings(TEMPLATES=[])
    def test_no_error_when_empty_templates_list(self):
        """No error when TEMPLATES list is empty."""
        errors = check_setting_app_dirs_loaders(self.app_configs)
        self.assertEqual(errors, [])

    @override_settings(TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "APP_DIRS": False,
        "OPTIONS": {"loaders": ["loader1"]},
    }])
    def test_no_error_when_app_dirs_explicitly_false(self):
        """No error when APP_DIRS explicitly set to False."""
        errors = check_setting_app_dirs_loaders(self.app_configs)
        self.assertEqual(errors, [])


class CheckStringIfInvalidIsStringTest(SimpleTestCase):
    """Tests for check_string_if_invalid_is_string function."""

    def setUp(self):
        self.app_configs = None

    @override_settings(TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "OPTIONS": {"string_if_invalid": ""}
    }])
    def test_no_error_when_string_if_invalid_is_empty_string(self):
        """No error when string_if_invalid is an empty string."""
        errors = check_string_if_invalid_is_string(self.app_configs)
        self.assertEqual(errors, [])

    @override_settings(TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "OPTIONS": {"string_if_invalid": "default value"}
    }])
    def test_no_error_when_string_if_invalid_is_valid_string(self):
        """No error when string_if_invalid is a valid string."""
        errors = check_string_if_invalid_is_string(self.app_configs)
        self.assertEqual(errors, [])

    @override_settings(TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "OPTIONS": {"string_if_invalid": 123}
    }])
    def test_error_when_string_if_invalid_is_integer(self):
        """Error when string_if_invalid is an integer."""
        errors = check_string_if_invalid_is_string(self.app_configs)
        self.assertEqual(len(errors), 1)
        self.assertIn("123", errors[0].msg)
        self.assertIn("int", errors[0].msg)

    @override_settings(TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "OPTIONS": {"string_if_invalid": None}
    }])
    def test_error_when_string_if_invalid_is_none(self):
        """Error when string_if_invalid is None."""
        errors = check_string_if_invalid_is_string(self.app_configs)
        self.assertEqual(len(errors), 1)
        self.assertIn("None", errors[0].msg)
        self.assertIn("NoneType", errors[0].msg)

