        """Error when string_if_invalid is a list."""
        errors = check_string_if_invalid_is_string(self.app_configs)
        self.assertEqual(len(errors), 1)
        self.assertIn("[]", errors[0].msg)
        self.assertIn("list", errors[0].msg)

    @override_settings(TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "OPTIONS": {"string_if_invalid": {}}
    }])
    def test_error_when_string_if_invalid_is_dict(self):
        """Error when string_if_invalid is a dict."""
        errors = check_string_if_invalid_is_string(self.app_configs)
        self.assertEqual(len(errors), 1)
        self.assertIn("{}", errors[0].msg)
        self.assertIn("dict", errors[0].msg)

    @override_settings(TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "OPTIONS": {"string_if_invalid": 3.14}
    }])
    def test_error_when_string_if_invalid_is_float(self):
        """Error when string_if_invalid is a float."""
        errors = check_string_if_invalid_is_string(self.app_configs)
        self.assertEqual(len(errors), 1)
