        from django.utils.text import Truncator
        self.Truncator = Truncator

    def test_chars_basic(self):
        t = self.Truncator('hello world')
        result = t.chars(3)
        self.assertEqual(result, 'hel…')

    def test_chars_no_truncation_needed(self):
        t = self.Truncator('hi')
        result = t.chars(10)
        self.assertEqual(result, 'hi')

    def test_chars_with_custom_truncate(self):
        t = self.Truncator('hello world')
        result = t.chars(3, truncate=' [truncated]')
        self.assertEqual(result, 'hel [truncated]')

    def test_chars_html_false(self):
        t = self.Truncator('<p>Hello</p>')
        result = t.chars(3, html=False)
        self.assertIn('<p', result)

    def test_chars_zero_length(self):
        t = self.Truncator('hello')
        result = t.chars(0)
        self.assertEqual(result, '…')

    def test_chars_combining_characters(self):
        # Combining characters should not count towards length
        t = self.Truncator('café')
        result = t.chars(3)
        self.assertLessEqual(len(result), 6)


